<?php require __DIR__.'/_start.php';$stepNames=[1=>'Hizmet',2=>'Uzman',3=>'Tarih',4=>'Saat',5=>'Özet',6=>'Onay']; ?>
<ol class="booking-steps" aria-label="Randevu adımları"><?php foreach($stepNames as $number=>$label): ?><li class="<?= $step===$number?'is-current':($step>$number?'is-done':'') ?>" <?= $step===$number?'aria-current="step"':'' ?>><span><?= $number ?></span><?= e($label) ?></li><?php endforeach ?></ol>
<p class="muted">Katalog tutarları örnek fiyatlardır; gerçek işletme tarifesi değildir. İllüstrasyonlu örnek uzman profilleri kurgusaldır.</p><?php if($step===1): ?><section class="customer-card"><div class="section-heading"><h2>Size uygun bakımı seçin</h2><a href="<?= e(url('customer/favorites')) ?>">Favori hizmetlerim</a></div><nav class="customer-tabs" aria-label="Hizmet kategorileri"><a class="<?= $category===''?'is-current':'' ?>" href="<?= e(url('customer/book')) ?>">Tümü</a><?php foreach($categories as $entry): ?><a class="<?= $category===$entry['category']?'is-current':'' ?>" href="<?= e(url('customer/book?category='.urlencode($entry['category']??''))) ?>"><?= e($entry['category']??'Diğer') ?></a><?php endforeach ?></nav><?php $serviceRows=$services;require __DIR__.'/_services.php'; ?></section>
<?php elseif($step===2): ?><section class="customer-card"><h2><?= e($service['name']) ?> için uzmanınızı seçin</h2><p class="muted">Yalnızca bu hizmete atanmış, aktif çalışanlar gösterilir.</p><?php if(!$workers): ?><p class="empty-state">Bu hizmet için şu anda atanmış bir uzman bulunmuyor.</p><a href="<?= e(url('customer/book')) ?>">Başka hizmet seçin</a><?php else: ?><form method="get" action="<?= e(url('customer/book')) ?>"><input type="hidden" name="step" value="3"><input type="hidden" name="service_id" value="<?= (int)$service['id'] ?>"><div class="worker-grid"><label class="worker-choice"><input type="radio" name="employee_id" value="any" required checked><span class="worker-avatar"><i class="bi bi-people" aria-hidden="true"></i></span><strong>Uygun herhangi bir uzman</strong><span>Seçtiğiniz saatte uygun çalışan onay sırasında atanır.</span></label>
<?php foreach($workers as $worker): $todaySlots=$worker['today_slots'];$assigned=$worker['services']; ?><label class="worker-choice"><input type="radio" name="employee_id" value="<?= (int)$worker['id'] ?>" required><?php if($worker['photo_path']): ?><img class="worker-avatar" src="<?= e(url($worker['photo_path'])) ?>" alt="<?= e($worker['name']) ?>"><?php else: ?><span class="worker-avatar"><?= e(mb_substr($worker['name'],0,1)) ?></span><?php endif ?><strong><?= e($worker['name']) ?></strong><span><?= e($worker['title']) ?></span><small><?= e($worker['bio']??'') ?></small><small>Hizmetler: <?= e(implode(', ',array_column($assigned,'name'))) ?></small><span class="availability-hint"><?= $todaySlots?count($todaySlots).' uygun saat bugün':'Bugün uygun saat yok; diğer tarihleri inceleyin.' ?></span></label><?php endforeach ?></div><div class="wizard-actions"><a class="btn btn-outline-dark" href="<?= e(url('customer/book')) ?>">← Hizmetler</a><button class="btn btn-lumera" type="submit">Tarih seç →</button></div></form><?php endif ?></section>
<?php elseif($step===3): ?>
<?php $base=['service_id'=>$service['id'],'employee_id'=>$employee?:'any'];if($reschedule){$base['reschedule']=$reschedule['id'];}$months=[1=>'Ocak',2=>'Şubat',3=>'Mart',4=>'Nisan',5=>'Mayıs',6=>'Haziran',7=>'Temmuz',8=>'Ağustos',9=>'Eylül',10=>'Ekim',11=>'Kasım',12=>'Aralık'];$previous=$monthStart->modify('-1 month');$next=$monthStart->modify('+1 month'); ?>
<section class="customer-card"><h2><?= $reschedule?'Randevunuz için yeni tarih':'Size uygun günü seçin' ?></h2><p><?= e($service['name']) ?> · <?= $employee?e((array_values(array_filter($workers,static fn($w)=>(int)$w['id']===$employee))[0]['name']??'')):'Uygun herhangi bir uzman' ?></p><div class="customer-calendar-header"><div><?php if($previous->modify('+1 month')>new DateTimeImmutable('today')): ?><a aria-label="Önceki ay" class="btn btn-outline-dark" href="<?= e(url('customer/book?'.http_build_query($base+['step'=>3,'month'=>$previous->format('Y-m')]))) ?>">←</a><?php endif ?></div><h3><?= e($months[(int)$monthStart->format('n')].' '.$monthStart->format('Y')) ?></h3><div><?php if($next<=$lastDay): ?><a aria-label="Sonraki ay" class="btn btn-outline-dark" href="<?= e(url('customer/book?'.http_build_query($base+['step'=>3,'month'=>$next->format('Y-m')]))) ?>">→</a><?php endif ?></div></div>
<div class="customer-calendar"><?php foreach(['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'] as $label): ?><span class="calendar-label"><?= e($label) ?></span><?php endforeach ?><?php for($blank=1;$blank<(int)$monthStart->format('N');$blank++): ?><span class="calendar-spacer" aria-hidden="true"></span><?php endfor ?><?php foreach($days as $day):$date=$day['date']->format('Y-m-d');if($day['count']): ?><a class="available-day <?= $date===date('Y-m-d')?'today':'' ?>" href="<?= e(url('customer/book?'.http_build_query($base+['step'=>4,'date'=>$date]))) ?>" aria-label="<?= e($day['date']->format('d.m.Y')) ?>, <?= $day['count'] ?> uygun saat"><strong><?= e($day['date']->format('j')) ?></strong><small><?= $day['count'] ?> saat</small></a><?php else: ?><button type="button" class="unavailable-day" disabled aria-label="<?= e($day['date']->format('d.m.Y')) ?>, uygun saat yok"><strong><?= e($day['date']->format('j')) ?></strong><small>Kapalı</small></button><?php endif;endforeach ?></div><p class="muted mt-3">Geçmiş tarihler, izinler, çalışma planı ve dolu saatler dikkate alınır. En fazla <?= $rules['booking_days'] ?> gün sonrası için seçim yapabilirsiniz.</p><a href="<?= e(url($reschedule?'customer/appointments/detail?id='.$reschedule['id']:'customer/book?step=2&service_id='.$service['id'])) ?>">← Geri</a></section>
<?php elseif($step===4): ?><section class="customer-card"><h2><?= e(date('d.m.Y',strtotime($date))) ?> için bir saat seçin</h2><p><?= e($service['name']) ?> · <?= $reschedule?(int)((strtotime($reschedule['end_at'])-strtotime($reschedule['start_at']))/60):(int)$service['duration_minutes'] ?> dakika</p><?php if(!$slots): ?><p class="empty-state">Bu günün saatleri dolmuş olabilir. Başka tarih seçin.</p><?php else: ?><form method="post" action="<?= e(url('customer/book/preview')) ?>" class="admin-form"><?= App\Core\Csrf::field() ?><input type="hidden" name="service_id" value="<?= (int)$service['id'] ?>"><input type="hidden" name="employee_id" value="<?= $employee?:'any' ?>"><input type="hidden" name="date" value="<?= e($date) ?>"><?php if($reschedule): ?><input type="hidden" name="reschedule" value="<?= (int)$reschedule['id'] ?>"><?php endif ?><div class="customer-slots"><?php foreach($slots as $time=>$candidateIds): ?><label><input name="time" type="radio" value="<?= e($time) ?>" required><span><?= e($time) ?></span></label><?php endforeach ?></div><?php if(!$reschedule): ?><label for="customer-note">Notunuz (isteğe bağlı)</label><textarea id="customer-note" name="customer_note" class="form-control" maxlength="1000" rows="3" placeholder="Uzmanınızın bilmesini istediğiniz bir şey var mı?"></textarea><?php endif ?><button class="btn btn-lumera" type="submit">Randevu özetini gör →</button></form><?php endif ?><?php $back=['step'=>3,'service_id'=>$service['id'],'employee_id'=>$employee?:'any','month'=>substr($date,0,7)];if($reschedule){$back['reschedule']=$reschedule['id'];} ?><a class="d-inline-block mt-3" href="<?= e(url('customer/book?'.http_build_query($back))) ?>">← Başka tarih seç</a></section>
<?php elseif($step===5): ?><section class="customer-card summary-card"><p class="eyebrow">SON BİR KONTROL</p><h2><?= isset($draft['reschedule'])?'Yeni randevu zamanınız':'Bakım planınız hazır' ?></h2><dl class="booking-summary"><dt>Hizmet</dt><dd><?= e($draft['service']['name']) ?></dd><dt>Çalışan</dt><dd><?= $draft['employee_id']?e((array_values(array_filter($draft['workers'],static fn($w)=>(int)$w['id']===$draft['employee_id']))[0]['name']??'')):'Uygun herhangi bir uzman (onayda atanır)' ?></dd><dt>Tarih / saat</dt><dd><?= e(date('d.m.Y',strtotime($draft['date'])).' '.$draft['time']) ?></dd><dt>Süre</dt><dd><?= (int)$draft['service']['duration_minutes'] ?> dakika</dd><dt>Tutar</dt><dd><?= e($money($draft['service']['price'])) ?></dd><dt>Not</dt><dd><?= e($draft['note']?:'Not eklenmedi') ?></dd></dl><p class="muted">Onayda müsaitlik sunucuda yeniden kontrol edilir. Bu aşamada ödeme alınmaz. Tarihi değişen randevu yeniden onay bekler.</p><form method="post" action="<?= e(url('customer/book/confirm')) ?>"><?= App\Core\Csrf::field() ?><input type="hidden" name="nonce" value="<?= e($draft['nonce']) ?>"><button class="btn btn-lumera" type="submit"><?= isset($draft['reschedule'])?'Tarih değişikliğini onayla':'Randevuyu onayla' ?> <i class="bi bi-check2 ms-2" aria-hidden="true"></i></button></form><a class="d-inline-block mt-3" href="<?= e(url('customer/book')) ?>">Seçimi yeniden başlat</a></section><?php endif ?>
